import{z as A,x as p,o as r,c as B,q as n,j as o,D as e,d as E,s as i,S as s,b as l}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"持续学习与回放","description":"","frontmatter":{"title":"持续学习与回放","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/continual-replay.md","filePath":"llm/continual-replay.md","lastUpdated":1791063341000}'),d={name:"llm/continual-replay.md"};function m(h,a,u,f,D,c){const t=p("Mermaid");return r(),B("div",null,[a[2]||(a[2]=n('<h1 id="持续学习与回放" tabindex="-1">持续学习与回放 <a class="header-anchor" href="#持续学习与回放" aria-label="Permalink to &quot;持续学习与回放&quot;">​</a></h1><div class="epigraph"><p>新任务的梯度会覆盖旧任务的解；把旧数据的一小撮再放进批次，是深度学习里最朴素也最有效的抗遗忘装置。</p><footer>—— 对照 Kirkpatrick 等 EWC（PNAS 2017）的参数约束；LLM 侧 Scialom 等 Fine-tuned Language Models are Continual Learners（EMNLP 2022）</footer></div><p><a href="/llm/rmu-wmdp">RMU</a>把一块领域推开之后，下一次领域 SFT 又可能把表示拉回来；更常见的是：客服 LoRA 之后再训代码，客服掉了。持续学习问的是任务序列 \\(T_1,T_2,\\ldots\\) 上如何更新。<a href="/llm/lora-vs-full-lr">灾难性遗忘</a>在全参大学习率下最烈；回放（replay / rehearsal）用 \\(T_{\\le i}\\) 的样本混合进 \\(T_{i+1}\\) 的批次。Scialom 等人表明指令模型靠回放可以连学多个任务。本课写回放与其它约束的分工。下一课专门把「忘了多少」写成指标。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>独立同分布假设在产品里不成立：本周上工具调用，下周上新语言，权重是一份。每次都从基座重训所有数据，存储与计算随任务线性涨，且<a href="/llm/instruction-data-lineage">谱系</a>各表要一直留着。只训新表，旧<a href="/llm/chat-template">模板</a>习惯与旧技能成为 \\(D_r\\)，遭受与未设计的遗忘同等的破坏。</p><p>EWC 用 Fisher 信息把重要参数钉住，不存旧数据。LLM 上 Fisher 贵、且指令任务共享大量参数，「重要」几乎是整网。实践默认是：<strong>存一小撮旧样本，混进新批次</strong>。缺口是：回放多少、按 token 还是按任务均匀、与<a href="/llm/response-only-loss">仅回复掩码</a>如何一起做。</p><h3 id="回放的是条件分布-不是「随便旧网页」" tabindex="-1">回放的是条件分布，不是「随便旧网页」 <a class="header-anchor" href="#回放的是条件分布-不是「随便旧网页」" aria-label="Permalink to &quot;回放的是条件分布，不是「随便旧网页」&quot;">​</a></h3><p>混入预训练网页可以稳住语言建模，但可能冲淡助手接口。应回放旧<strong>指令</strong>（及必要的领域全文，若做过 DAPT）。比例是超参：太少无效，太多新任务学不动。</p><p><span class="marginnote">梯度情景记忆（GEM，Lopez-Paz 与 Ranzato）约束新梯度不增加旧损失，实现重。LLM SFT 上少见，回放更常见。LAMOL 等用模型自己生成伪旧样本，质量取决于当前遗忘程度，会自我放大错误。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>维护每个已上线任务的回放池：分层抽样覆盖该任务的模板与难度，体积可远小于原集（百分之几到固定 \\(N\\) 条）。训 \\(T_{i+1}\\) 时，每个有效批次含 \\(p\\) 比例回放，\\(1-p\\) 新数据。损失仍仅回复；打包时切断样本，避免新旧对话拼成假多轮。学习率沿用该阶段的<a href="/llm/lora-vs-full-lr">LoRA/全参分叉</a>，新任务想学快就加大新数据比重，而不是只加大 \\(\\eta\\) 去碾旧知识。</p><p><span class="marginnote">数字感受一下 \\(p\\)：批次 64 条、\\(p=0.25\\)，意味着每批有 16 条旧样本、48 条新样本——旧任务在每一步都保有四分之一的话语权，而存储上这些旧样本可能只占原数据集的百分之一二，这就是回放「以小博大」的地方。</span></p><p>检查点策略：保留 \\(T_i\\) 结束的权重，直到 \\(T_{i+1}\\) 的回放配方通过旧任务回归。LoRA 可选择新任务新适配器、旧任务旧适配器，用<a href="/llm/lora-merge-conflict">切换而非合并</a>来回避持续学习——那是存储换干扰，不是本课的单权重方案。</p>',13)),(r(),o(s,null,{default:e(()=>[i(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20LR%0A%20%20T1%5B%22%E4%BB%BB%E5%8A%A1%E6%B1%A0%201%22%5D%20--%3E%20MIX%5B%22%E6%8C%89%E6%AF%94%E4%BE%8B%E6%B7%B7%E5%90%88%E6%89%B9%E6%AC%A1%22%5D%0A%20%20T2%5B%22%E6%96%B0%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20MIX%0A%20%20MIX%20--%3E%20SFT%5B%22%E4%BB%85%E5%9B%9E%E5%A4%8D%20SFT%22%5D%0A%20%20SFT%20--%3E%20REG%5B%22%E6%97%A7%E4%BB%BB%E5%8A%A1%E5%9B%9E%E5%BD%92%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("p",null,"与 RMU 连用：危险领域不要进回放池。回放是保护 \\(D_r\\)，不是把 \\(D_f\\) 救回来。",-1)),a[4]||(a[4]=l("h2",{id:"机制",tabindex:"-1"},[E("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=l("p",null,"SGD 对当前批次损失下降。没有旧样本时，旧任务的损失不在目标里，参数沿新任务梯度离开旧盆地。回放把旧损失重新放进同一求和，最优折中点在新旧盆地之间。这不是无偏恢复「从未顺序学习」的联合训练——顺序与配比会偏新或偏旧——但是可调。EWC 用二次惩罚近似同一折中，不碰数据；当 Fisher 不准时，钉错参数，新任务也学不好。",-1)),a[6]||(a[6]=l("p",null,"回放与 EWC 是逼近同一个「新旧折中」的两条路，差别值得画出来：",-1)),(r(),o(s,null,{default:e(()=>[i(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20Q%5B%22%E5%8F%82%E6%95%B0%E8%A6%81%E5%9C%A8%E6%96%B0%E6%97%A7%E4%BB%BB%E5%8A%A1%E9%97%B4%E6%8A%98%E4%B8%AD%22%5D%20--%3E%20R%5B%22%E5%9B%9E%E6%94%BE%3A%E6%8A%8A%E6%97%A7%E6%8D%9F%E5%A4%B1%E6%94%BE%E5%9B%9E%E5%90%8C%E4%B8%80%E6%89%B9%E6%AC%A1%22%5D%0A%20%20Q%20--%3E%20E%5B%22EWC%3A%E7%94%A8%E4%BA%8C%E6%AC%A1%E6%83%A9%E7%BD%9A%E9%92%89%E4%BD%8F%E9%87%8D%E8%A6%81%E5%8F%82%E6%95%B0%22%5D%0A%20%20R%20--%3E%20R1%5B%22%E6%AF%8F%E6%AD%A5%E9%83%BD%E7%9C%8B%E5%BE%97%E8%A7%81%E6%97%A7%E6%A2%AF%E5%BA%A6%2C%E6%8A%98%E4%B8%AD%E7%82%B9%E5%8F%AF%E8%B0%83%22%5D%0A%20%20E%20--%3E%20E1%5B%22%E4%B8%8D%E7%94%A8%E5%AD%98%E6%95%B0%E6%8D%AE%2C%E4%BD%86%E4%BE%9D%E8%B5%96%20Fisher%20%E4%BC%B0%E5%BE%97%E5%87%86%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">可以打个比方：回放是「把旧课本摊在桌边，一边学新课一边回头翻」，EWC 是「给旧笔记上锁，规定哪些页不许涂改」。前者花存储、每步都生效；后者省存储，但锁的位置估错了就两头都坏。</span></p><p><a href="/llm/lora">LoRA</a> 的低维更新减少漂移，有时能少回放；多任务仍要回放或切换适配器，否则同一 \\(BA\\) 被新任务覆写。ReLoRA 合并进 \\(W\\) 后旧适配器消失，更依赖回放。</p><p><span class="marginnote">长上下文阶段若只回放短样本，短能力在，长能力仍会掉，反之亦然。回放池要按你声明要保持的轴分层。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>法律上的删除与回放冲突：若 \\(T_1\\) 含必须遗忘的用户数据，回放池必须先按<a href="/llm/machine-unlearning">遗忘</a>清洗，否则回放在对抗遗忘。存储回放涉及隐私，需与原数据同等管控。任务极多时，固定体积池 + 类均衡抽样，避免早期任务被挤出。无回放的「只训 LoRA 然后合并」会把持续学习问题变成合并冲突问题，并不消失。</p><p><span class="marginnote">为什么「遗忘集不得进回放池」是硬约束：回放的原理恰恰是反复重放旧样本。若被要求删除的用户数据还躺在池里，每训练一步就等于把它多学一遍——删除义务与学习机制正面相撞，只能先清洗、再回放。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>顺序 SFT 会覆盖旧任务；回放把旧指令按比例混回批次。</li><li>回放的是要对齐的条件分布，不是随机网页。</li><li>用旧任务回归做早停，不要只用新任务 NLL。</li><li>LoRA 减少但不会取消覆写；切换适配器是另一条产品路。</li><li>遗忘集不得进入回放池。</li><li>出处：Kirkpatrick 等，EWC，PNAS 2017；Scialom 等，EMNLP 2022；回放作为持续学习的基线装置。</li></ul>',8))])}const L=A(d,[["render",m]]);export{T as __pageData,L as default};
